import React, { PropsWithChildren } from 'react';

import type { _SpinButtonGroupSeparatorProps } from './types.js';

/**
 * Used to define a trigger between spinbuttons. e.g. the colon within a time value 12:34.
 */
export const SpinButtonGroupSeparator = ({
  children,
  ...props
}: PropsWithChildren<_SpinButtonGroupSeparatorProps>) => {
  return <span>{children ?? props.trigger}</span>;
};
